// Native article module for the existing concept/chaos route.
const markup="<div class=\"page-shell dao-reading chaos-reading\" data-chaos-page>\n<nav class=\"breadcrumbs\" aria-label=\"当前位置\"><a href=\"#/tian\">天道</a><span aria-hidden=\"true\">/</span><a href=\"#/map?focus=origin\">本源</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">一：混沌</span></nav>\n<header class=\"page-heading\"><span class=\"eyebrow\">TIAN / 本源 / 1.2</span><h1>一：混沌</h1><p class=\"chaos-definition\">还没有成为具体的万物，<br>却具有形成万物的能力。</p><p class=\"page-intro\">从“万物的根源是什么”，继续追问：当万物的区别尚未展开时，生成它们的可能，以怎样的方式存在？</p></header>\n<figure class=\"opening-illustration\"><img src=\"/assets/chaos/混沌未分.jpg\" width=\"2048\" height=\"683\" alt=\"淡墨在米色纸上流动，边缘渐显山水轮廓，中央仍为未分的雾气\" fetchpriority=\"high\"><figcaption>由未分，到成形 · 一幅关于潜能的意象</figcaption></figure>\n<div class=\"article-layout\"><aside class=\"article-toc\"><span class=\"eyebrow\">本页内容</span><button type=\"button\" data-scroll=\"chaos-root\">01 道生一</button><button type=\"button\" data-scroll=\"chaos-potential\">02 未分与潜能</button><button type=\"button\" data-scroll=\"chaos-hyle\">03 Hyle与生成</button><button type=\"button\" data-scroll=\"chaos-emptiness\">04 空性与潜能</button><button type=\"button\" data-scroll=\"chaos-abyss\">05 渊与显现</button><button type=\"button\" data-scroll=\"chaos-physics\">06 物理对读</button><button type=\"button\" data-scroll=\"chaos-whole\">07 本自具足</button></aside><article class=\"prose chaos-body\">\n<section class=\"section\" id=\"chaos-root\" aria-labelledby=\"chaos-root-title\">\n<div class=\"section-title\"><span class=\"num\">01</span><h2 id=\"chaos-root-title\">道生一：从根源，走向潜能</h2></div>\n<p class=\"lede\">“道”回答生成从何而来；“一”说明万物尚未分化时的整体。</p>\n<div class=\"prose\"><p>上一节从山川、星辰与生命追问共同的根源。在这一节，我们把目光移向具体形态出现以前：当山还没有山的轮廓，水还没有水的流向，万物尚不能被逐一指出时，怎样理解它们得以形成的可能？</p><p>沿“道生一”的主线，“一”指未分化的整体，“混沌”说明它的状态。<strong>道是生成的根源；混沌是这份生成能力尚未展开为具体万物时的整体状态。</strong>由根源进入潜能，问题便向前推进了一步。</p></div>\n<div class=\"concept-flow\" aria-label=\"道生一的解释关系\"><div class=\"node\">道<small>生成的根源</small></div><span class=\"arrow\" aria-hidden=\"true\">→</span><div class=\"node\">生<small>根源与潜能的关系</small></div><span class=\"arrow\" aria-hidden=\"true\">→</span><div class=\"node\">一<small>未分化的整体</small></div></div>\n<div class=\"pair\"><div><small>1.1 · 生成的根源</small><h3>Nous → 道／源头</h3><p>借神圣心智讨论根源的意识性、认识与创造能力。</p></div><div><small>1.2 · 未分化的整体</small><h3>Hyle → 一／混沌</h3><p>借尚未取得形式的质料，讨论生成的潜能与成形的可能。</p></div></div>\n<p class=\"note\">Nous 与道、Hyle 与一的联系，是关于根源与潜能的哲学对读。“道生一”的解释承接，与宇宙早期的具体年代和物理过程，各有不同的问题与尺度。</p>\n</section>\n<section class=\"section\" id=\"chaos-potential\" aria-labelledby=\"chaos-potential-title\">\n<div class=\"section-title\"><span class=\"num\">02</span><h2 id=\"chaos-potential-title\">混沌：尚未成形，同时能够生成</h2></div>\n<div class=\"prose\"><p>在日常语言里，混沌容易使人想到杂乱、混合与难以辨认。这里的“混沌”着重指更深一层的“未分化”：山、水、叶子的区别尚未展开，具体事物还没有获得各自的形式。</p><p>这个定义包含两个同时成立的方面：<strong>尚未成为具体的万物，具有形成万物的能力。</strong>前者说明当下的状态，后者说明生成的可能。理解混沌，需要把两方面放在一起。</p></div>\n<div class=\"prose\"><h3>未分化，具体意味着什么？</h3><p>《与神对话》从“一切万有”展开叙述：整体之外没有另一个存在供它参照。没有此与彼的分别，便还没有“我是这一个，而非那一个”的特定身份经验。书中同时保留了整体在概念上知道自身的描述。</p><p>依这一叙述，未分化说明差异与身份关系尚未展开，整体自身仍有认识与生成能力。道与一由此有不同的解释位置，同时保持根源与整体的连续：我们沿同一整体追问根源、潜能及其展开。</p></div>\n<div class=\"meaning\"><div><span class=\"label\">尚未成形</span><h3>区别尚未展开</h3><p>还没有可逐一辨认的山、水、星辰与生命。</p></div><div><span class=\"label\">能够生成</span><h3>形式仍可出现</h3><p>未成形之中蕴含生成能力，具体呈现有待展开。</p></div></div>\n<figure class=\"figure\" aria-labelledby=\"chaos-potential-figure-title\"><div class=\"eyebrow\">概念示意 · 点击三个位置</div><h3 id=\"chaos-potential-figure-title\">从“尚未成为”，理解“能够成为”</h3>\n<svg class=\"desktop-viz\" viewBox=\"0 0 780 280\" role=\"img\" aria-labelledby=\"chaos-potential-svg-title chaos-potential-svg-desc\"><title id=\"chaos-potential-svg-title\">潜能与形式的关系</title><desc id=\"chaos-potential-svg-desc\">三个位置分别呈现未取得形式、进入活动和具体形式。按钮用于逐步查看，图形不表示宇宙真实的创生外观。</desc><defs><radialGradient id=\"chaos-potential-mist\"><stop stop-color=\"#94a48b\" stop-opacity=\".7\"/><stop offset=\"1\" stop-color=\"#94a48b\" stop-opacity=\"0\"/></radialGradient></defs><path d=\"M194 135H300M465 135H573\" stroke=\"#c2ccbd\" stroke-width=\"1.5\" stroke-dasharray=\"4 6\"/><g class=\"stage-form\" id=\"chaos-stage-0\"><circle cx=\"125\" cy=\"132\" r=\"96\" fill=\"url(#chaos-potential-mist)\"/><circle cx=\"125\" cy=\"132\" r=\"65\" fill=\"none\" stroke=\"#7d9279\" stroke-dasharray=\"2 7\"/><text class=\"svg-major\" x=\"125\" y=\"246\" text-anchor=\"middle\">未取得形式</text></g><g class=\"stage-form\" id=\"chaos-stage-1\"><circle cx=\"390\" cy=\"132\" r=\"87\" fill=\"url(#chaos-potential-mist)\"/><path d=\"M331 156Q315 85 382 73T450 143 380 185 350 115 420 102\" fill=\"none\" stroke=\"#6e886c\" stroke-width=\"2\"/><text class=\"svg-major\" x=\"390\" y=\"246\" text-anchor=\"middle\">潜能进入活动</text></g><g class=\"stage-form\" id=\"chaos-stage-2\"><path d=\"M598 173L621 126 638 144 664 86 704 173Z\" fill=\"#5f7865\" opacity=\".8\"/><path d=\"M606 190Q641 169 665 186T723 182\" stroke=\"#7d9993\" stroke-width=\"4\" fill=\"none\"/><path d=\"M666 63Q658 42 676 33Q695 47 666 63Z\" fill=\"#9eac83\"/><text class=\"svg-major\" x=\"660\" y=\"246\" text-anchor=\"middle\">具体形式出现</text></g></svg>\n<div class=\"mobile-viz mobile-stages\" aria-label=\"潜能与形式的三个位置\"><div data-mobile-stage=\"0\"><span class=\"stage-glyph\" aria-hidden=\"true\">◌</span><strong>未取得形式</strong></div><span class=\"mobile-arrow\" aria-hidden=\"true\">↓</span><div data-mobile-stage=\"1\"><span class=\"stage-glyph\" aria-hidden=\"true\">≈</span><strong>潜能进入活动</strong></div><span class=\"mobile-arrow\" aria-hidden=\"true\">↓</span><div data-mobile-stage=\"2\"><span class=\"stage-glyph\" aria-hidden=\"true\">山</span><strong>具体形式出现</strong></div></div>\n<div class=\"choices\" aria-label=\"选择潜能示意阶段\"><button class=\"choice\" type=\"button\" data-stage=\"0\" aria-pressed=\"true\">未取得形式</button><button class=\"choice\" type=\"button\" data-stage=\"1\" aria-pressed=\"false\">进入活动</button><button class=\"choice\" type=\"button\" data-stage=\"2\" aria-pressed=\"false\">具体形式</button></div>\n<div class=\"readout\" id=\"chaos-stage-note\" aria-live=\"polite\"><strong>未取得形式：</strong>这里强调具体区别尚未展开，同时保留能够生成的可能。</div><figcaption class=\"caption\">三个位置帮助理解状态与生成的关系；图中出现的山水，只是“具体形式”的示意。</figcaption></figure>\n<div class=\"prose\"><p>潜能意味着形式尚待展开。若只看到“尚未成为”，便容易把混沌想成一片绝无可能的空白；若把“具有能力”理解成已经存放了全部成品，又会让“生成”失去意义。<strong>万物的可能，可以先于万物的具体形态被讨论。</strong></p><p>这里的“先于”首先说明解释次序：我们由已经成形的事物，追问它得以成形的条件与能力。尚未显出的能力，仍需要通过具体展开才能获得形式。</p></div>\n</section>\n<section class=\"section\" id=\"chaos-hyle\" aria-labelledby=\"chaos-hyle-title\">\n<div class=\"section-title\"><span class=\"num\">03</span><h2 id=\"chaos-hyle-title\">Hyle：无形怎样进入生成</h2></div>\n<div class=\"prose\"><p>赫尔墨斯传统中的 <em>Hyle</em>，通常译作“质料”。它与“一／混沌”的对读，着重说明尚未取得形式、又能进入生成的含义。</p></div>\n<blockquote class=\"quote\">质料未生的状态，就是无形；<br>它的生成，就是被带入活动。<cite>《赫尔墨斯残篇 V·论质料》 · 据 Mead 英译</cite><span class=\"original\" lang=\"en\">“The unborn state of Matter, then, was formlessness; its genesis is its being brought into activity.”</span></blockquote>\n<div class=\"prose\"><h3>质料是“生成之器”</h3><p>原段此前把质料称为“生成之器”，并把生成称为神的活动方式；接着描述质料接受生成的种子，发生变化，取得形式。“器”在这里给出承载与受形的角色，使根源、质料与生成活动的关系更具体。</p><p>Nous／道指向创造的根源，Hyle／一指向承载生成、尚未成形的潜能。由此再看“道生一”，我们就能继续问：根源的生成能力怎样成为可展开的潜能，而潜能又怎样在活动中取得形式？</p></div>\n<figure class=\"figure art-figure\" aria-labelledby=\"chaos-clay-title\"><div class=\"eyebrow\">日常类比 · 潜能与形式</div><h3 id=\"chaos-clay-title\">一团泥，可以成为什么？</h3><div class=\"clay-canvas\"><img src=\"/assets/chaos/潜能与成形.jpg\" width=\"1672\" height=\"941\" loading=\"lazy\" alt=\"同一质感的泥团与碗、瓶、鸟，三种已成形式作为泥的不同可能并置\"><svg viewBox=\"0 0 1672 941\" aria-hidden=\"true\" class=\"art-overlay\"><defs><mask id=\"chaos-clay-mask\"><rect width=\"1672\" height=\"941\" fill=\"white\"/><ellipse cx=\"847\" cy=\"653\" rx=\"424\" ry=\"252\" fill=\"black\"/><ellipse id=\"chaos-clay-hole\" cx=\"333\" cy=\"275\" rx=\"276\" ry=\"203\" fill=\"black\"/></mask></defs><rect id=\"chaos-clay-veil\" width=\"1672\" height=\"941\" fill=\"#efeee8\" opacity=\"0\" mask=\"url(#chaos-clay-mask)\"/><ellipse id=\"chaos-clay-ring\" cx=\"333\" cy=\"275\" rx=\"276\" ry=\"203\" fill=\"none\" stroke=\"#96784b\" stroke-width=\"3\" stroke-dasharray=\"8 9\" opacity=\"0\"/></svg></div><div class=\"choices\" aria-label=\"选择泥的不同成形可能\"><button class=\"choice\" type=\"button\" data-clay=\"all\" aria-pressed=\"true\">看潜能</button><button class=\"choice\" type=\"button\" data-clay=\"bowl\" aria-pressed=\"false\">成碗</button><button class=\"choice\" type=\"button\" data-clay=\"vase\" aria-pressed=\"false\">成瓶</button><button class=\"choice\" type=\"button\" data-clay=\"bird\" aria-pressed=\"false\">成鸟</button></div><p class=\"readout\" id=\"chaos-clay-note\" aria-live=\"polite\"><strong>多种可能：</strong>泥团尚未成为碗、瓶或鸟，却可以在相应的塑形活动中，取得其中一种形式。</p><figcaption class=\"caption\">三件物表示并列的成形可能。泥土已经是一种具体材料，这里借它说明材料与形式的关系；Hyle 的讨论尺度仍依前文理解。</figcaption></figure>\n<div class=\"split\"><div class=\"prose\"><h3>未生、活动、形式</h3><p>原段把“未生”与“无形”联系起来，再把“生成”说明为进入活动。相邻段落把质料称为生成的承受者，并联系接受形式与变化。</p><p>于是，“无形”与“有形”之间有了可追问的联系：质料能够接受形式，在活动中变化，成为具体的存在。<strong>生成，使尚未成形的可能获得确定的呈现。</strong></p></div><div class=\"prose\"><h3>“质料”的理解尺度</h3><p>日常的泥土、木材与金属，已经具有各自的性质和结构。Hyle 在这里帮助我们把问题推向这些具体材料之前：如何谈论尚未规定为某一种事物、又能取得形式的可能？</p><p>尚未取得具体形式，又能进入生成，使 Hyle 与混沌产生联系。赫尔墨斯文本与《道德经》各有自身的语境；这层联系帮助理解潜能与形式，不能据此将两套思想完全等同。</p></div></div>\n<p class=\"note\">借 Hyle 回看本节定义，“尚未成为”对应未成形，“具有能力”对应能够进入生成。这个联系使“混沌”从一个模糊的名称，变成关于潜能与形式的具体问题。</p>\n<details class=\"action-fold dao-fold\"><summary>古典文本中的“活动”与“承载”</summary><div class=\"inside action-prose\"><p>Mead 在这段古典文本中用 energy 表示活动／作用；其译注以 receptacle 或 field 说明“生成之器”。阅读时沿古典的活动与承载域理解这些词。后文海森堡所谈的物理能量、现代量子场，各有自己的定义与理论。</p></div></details>\n</section>\n<section class=\"section\" id=\"chaos-emptiness\" aria-labelledby=\"chaos-emptiness-title\">\n<div class=\"section-title\"><span class=\"num\">04</span><h2 id=\"chaos-emptiness-title\">空性与潜能：事物怎样保持开放</h2></div>\n<div class=\"prose\"><p>讨论潜能时，会遇到一个问题：一件事物若从自身一面就已经固定成某种样子，完全不依赖条件，它又怎样与条件发生关系，呈现不同的可能？空性使我们能够继续追问事物的存在方式。</p><h3>空的是什么？</h3><p>佛教所说的“无自性”，指事物没有一种凭自身独立成立、不依待其他条件的本性。具体事物依待原因、组成部分以及相应关系而成立。依这一理解，空性说明的是：我们所经验的存在，如何在依存中成立。</p><p>《心经》说“色不异空，空不异色”；《维摩诘经》用“色性自空”说明：具体的色法，当下就是无自性的。我们可以一边看见一朵花，一边理解它依待条件而存在；无需等花消失以后，再另找一种“空”。</p></div>\n<figure class=\"figure art-figure\" aria-labelledby=\"chaos-flower-title\"><div class=\"eyebrow\">同一朵花 · 形态与依待</div><h3 id=\"chaos-flower-title\">花已成形，仍然依待条件</h3><div class=\"flower-canvas\"><img src=\"/assets/chaos/花与条件.jpg\" width=\"1672\" height=\"941\" loading=\"lazy\" alt=\"白花与绿色枝叶立于土壤中，根系、阳光、水分与种子各有位置\"><svg class=\"art-overlay\" viewBox=\"0 0 1672 941\" aria-hidden=\"true\"><g id=\"chaos-flower-guides\" opacity=\"0\"><path d=\"M233 148Q436 187 646 316M1371 236Q1074 269 819 398M1452 778Q1104 843 737 726M705 786L705 470\" fill=\"none\" stroke=\"#876c41\" stroke-width=\"2\" stroke-dasharray=\"6 8\"/></g><ellipse id=\"chaos-flower-focus\" cx=\"226\" cy=\"147\" rx=\"140\" ry=\"123\" fill=\"#c6aa7c\" fill-opacity=\".08\" stroke=\"#876c41\" stroke-width=\"3\" stroke-dasharray=\"6 8\" opacity=\"0\"/></svg></div><div class=\"choices\" aria-label=\"选择花的观察方式\"><button class=\"choice\" type=\"button\" data-flower=\"form\" aria-pressed=\"true\">看见形态</button><button class=\"choice\" type=\"button\" data-flower=\"conditions\" aria-pressed=\"false\">看见依待</button><button class=\"choice\" type=\"button\" data-flower=\"empty\" aria-pressed=\"false\">理解无自性</button></div><div id=\"chaos-flower-condition-picker\" hidden><p class=\"picker-label\">选择一个条件，观察它怎样参与：</p><div class=\"choices condition-picker\" aria-label=\"选择花所依待的条件\"><button class=\"choice\" type=\"button\" data-condition=\"light\" aria-pressed=\"false\">阳光</button><button class=\"choice\" type=\"button\" data-condition=\"water\" aria-pressed=\"false\">水分</button><button class=\"choice\" type=\"button\" data-condition=\"soil\" aria-pressed=\"false\">土壤与根系</button><button class=\"choice\" type=\"button\" data-condition=\"seed\" aria-pressed=\"false\">种子与过程</button><button class=\"choice\" type=\"button\" data-condition=\"name\" aria-pressed=\"false\">辨认与命名</button></div></div><p id=\"chaos-flower-note\" class=\"readout\" aria-live=\"polite\"><strong>看见形态：</strong>一朵花已经成形，具有可以辨认的样子。</p><figcaption class=\"caption\">生长条件与辨认方式各有作用。图中植物始终保留：空性说明它怎样存在。</figcaption></figure>\n<div class=\"prose\"><h3>罗奇为什么用“潜能”讲空性？</h3><p>麦克·罗奇在《能断金刚》中写道：</p></div>\n<blockquote class=\"quote\">金刚在藏传佛教中代表了一切事物所隐含的潜能：通常被称作“空性”。<cite>麦克·罗奇《能断金刚》</cite></blockquote>\n<div class=\"prose\"><p>这给“空性与潜能”的对读提供了直接入口：事物没有被独立、固定的自性锁定，其具体呈现需要条件参与。我们由此能够讨论条件改变时，事物如何形成与变化。</p><p>《能断金刚》还借金刚作比喻，讨论诸事物共同的终极本性。与其 ACI 第六课程材料连读，这种“相同”得到更清楚的解释：<strong>各处空性，都同样是自性存在的缺席。</strong>共同没有自性，并不由此成为同一块隐形材料。</p><p>无自性使“固定不变、完全独立”的理解得到松动；一种可能怎样实现，仍须说明它依待的条件。花要开放，需要相应的生长条件。“潜能”在这里始终与依待和生成一起理解。</p></div>\n<h3>空性与混沌，分别回答什么？</h3>\n<table class=\"concept-table\"><thead><tr><th scope=\"col\">概念</th><th scope=\"col\">解释的重点</th><th scope=\"col\">适用的位置</th></tr></thead><tbody><tr><th scope=\"row\">混沌</th><td>万物尚未分化，具有形成万物的能力。</td><td>未分化整体的状态。</td></tr><tr><th scope=\"row\">空性</th><td>具体存在无独立自性，依待条件而成立。</td><td>也适用于已经成形的万物。</td></tr><tr><th scope=\"row\">潜能</th><td>从尚未成为，理解能够成为。</td><td>连接条件、活动与形式的问题。</td></tr></tbody></table>\n<p class=\"note\"><strong>空性说明存在方式；混沌说明未分化状态。</strong>无自性使具体呈现保持对条件的依待；已经成形的事物，同样具有空性。</p>\n<details class=\"action-fold dao-fold\"><summary>理解空性，先辨清所否定的是什么</summary><div class=\"inside action-prose\"><p>ACI 课件强调，理解空性之前要先明确被否定的自性存在。把它读成“花不存在”，会漏掉依待而有的层次；把共同空性读成万物融入一个实体，则又引入了课件未主张的本体。罗奇还区分两条认识路径：通过阅读与仔细思考理解空性，以及在深度冥想中直接证悟。概念理解与直接证悟，所指的认识层次不同。</p></div></details>\n</section>\n<section class=\"section\" id=\"chaos-abyss\" aria-labelledby=\"chaos-abyss-title\">\n<div class=\"section-title\"><span class=\"num\">05</span><h2 id=\"chaos-abyss-title\">渊：显出的形态，未尽的深广</h2></div>\n<blockquote class=\"quote\">道冲，而用之或不盈。<br>渊兮，似万物之宗。<cite>《道德经》第四章</cite></blockquote>\n<div class=\"split wide-left\"><div class=\"prose\"><p>“渊”给出一个深而难以穷尽的意象。借这个意象，我们可以把尚未显现的潜能想作一片深海：浪有可见的轮廓，海仍有这一轮廓没有显出的深广。</p><p>每一道浪呈现一种形状，海的可能并未被这一种形状用尽。由可见的显现继续追问，便会注意到支撑显现、又超出当前形态的背景。</p><p>《道德经》以“渊”形容道。借它的深广意象，也可以思考混沌与潜能，体会未显与显现、整体与具体形态之间的关系。</p></div><figure class=\"figure\" style=\"margin-top:0\"><svg viewBox=\"0 0 460 300\" role=\"img\" aria-labelledby=\"chaos-sea-title chaos-sea-desc\"><title id=\"chaos-sea-title\">海与浪的意象</title><desc id=\"chaos-sea-desc\">表层波浪之下，淡色水纹向深处延展。切换可查看浪形或深广背景。</desc><defs><linearGradient id=\"chaos-sea-grad\" x2=\"0\" y2=\"1\"><stop stop-color=\"#c4d1c0\" stop-opacity=\".55\"/><stop offset=\"1\" stop-color=\"#577768\" stop-opacity=\".18\"/></linearGradient></defs><g id=\"chaos-sea-detail\"><path d=\"M8 105Q55 55 105 105T202 105 300 105 398 105T452 105V282H8Z\" fill=\"url(#chaos-sea-grad)\"/><path d=\"M15 155Q70 120 125 155T235 155 345 155 450 155M15 207Q70 175 125 207T235 207 345 207 450 207M15 258Q70 233 125 258T235 258 345 258 450 258\" stroke=\"#6d8976\" opacity=\".25\" fill=\"none\"/></g><path d=\"M8 105Q55 55 105 105T202 105 300 105 398 105T452 105\" id=\"chaos-sea-wave\" fill=\"none\" stroke=\"#315d50\" stroke-width=\"2\"/><text class=\"svg-label\" x=\"230\" y=\"44\" text-anchor=\"middle\">可见的形态</text><text class=\"svg-label\" x=\"230\" y=\"245\" text-anchor=\"middle\" id=\"chaos-sea-depth-label\">尚未尽显的深广</text></svg><div class=\"choices\" aria-label=\"选择海与浪的视角\"><button class=\"choice\" type=\"button\" data-sea=\"wave\" aria-pressed=\"false\">看浪形</button><button class=\"choice\" type=\"button\" data-sea=\"whole\" aria-pressed=\"true\">看海与浪</button></div><figcaption class=\"caption\" id=\"chaos-sea-note\" aria-live=\"polite\">这一道浪显出形状，海仍有超出这一形状的深广。</figcaption></figure></div>\n<p class=\"note\">海与浪是一种意象。它帮助提出“当前显现是否穷尽整体”的问题；Hyle、空性与物理真空各自的含义，仍沿各自来源展开。</p>\n</section>\n<section class=\"section\" id=\"chaos-physics\" aria-labelledby=\"chaos-physics-title\">\n<div class=\"section-title\"><span class=\"num\">06</span><h2 id=\"chaos-physics-title\">物理对读：潜能、背景与激发</h2></div>\n<div class=\"prose\"><p>“尚未显现，却具有形成能力”的思路，在现代物理及物理学家的哲学讨论中，也有可以认真比较的对象。把比较拆开，才看得清每个概念照亮了哪一种关系。</p></div>\n<div class=\"comparison\">\n<div class=\"comparison-item\"><span class=\"mark\" aria-hidden=\"true\">Ⅰ</span><div><h3>海森堡：潜能怎样取得形式</h3><p>海森堡在《物理学与哲学》第九章，借亚里士多德的 <em>potentia</em>（潜能）讨论质料，并将其与现代物理中的能量比较。他进一步借“形式”理解基本粒子的现实化。</p><p>这条对读与 Hyle 直接接壤：未取得某种具体形式，与能够在一定结构中取得形式，可以一起思考。它帮助我们把“可能”与“已成之物”分清，再追问两者怎样联系。</p><p class=\"scope\">这出自海森堡本人的哲学比较。“潜能”也没有因此成为一种正式命名为“潜能场”的新物理实体。</p></div></div>\n<div class=\"comparison-item\"><span class=\"mark\" aria-hidden=\"true\">Ⅱ</span><div><h3>量子真空：没有粒子激发，理论结构仍在</h3><p>在通常平直时空的自由量子场描述中，真空是没有粒子激发的最低能量状态。场、场的状态与粒子激发，分别承担不同含义。</p><p><strong>“尚无粒子激发”仍然预设一个有结构的物理理论。</strong>真空已有相应的场、规律与允许的激发；它使我们能够比较“没有具体激发”与“连使激发成为可能的结构也不存在”的区别。</p><p class=\"scope\">比较的重点是背景与具体显现。物理可能性受理论、能量与守恒条件约束；真空自身也有量子相关和涨落，不能简单画作完全静止的空容器。</p></div></div>\n</div>\n<figure class=\"figure field-comparison\" id=\"chaos-field-comparison\" aria-labelledby=\"chaos-vacuum-title\">\n<div class=\"eyebrow\">混沌 · Hyle · 渊 / 基态与潜能</div><h3 id=\"chaos-vacuum-title\">尚无具体激发，结构仍在</h3>\n<div class=\"field-layout\">\n<div class=\"field-visual\">\n<div class=\"field-scene\" id=\"chaos-field-scene\" data-field-state=\"ground\" role=\"img\" aria-label=\"基态：层叠细线表示始终存在的理论结构，没有电子或正电子激发\">\n<svg class=\"field-pattern\" viewBox=\"0 0 640 320\" preserveAspectRatio=\"none\" aria-hidden=\"true\"><defs><radialGradient id=\"chaos-field-haze\"><stop stop-color=\"#9aa98e\" stop-opacity=\".32\"/><stop offset=\"1\" stop-color=\"#9aa98e\" stop-opacity=\"0\"/></radialGradient></defs><ellipse cx=\"324\" cy=\"164\" rx=\"300\" ry=\"158\" fill=\"url(#chaos-field-haze)\"/><g class=\"field-modes\"><path d=\"M-30 34C75 0 132 65 236 36S414 2 512 38 642 54 680 28\"/><path d=\"M-30 57C75 23 132 88 236 59S414 25 512 61 642 77 680 51\"/><path d=\"M-30 80C75 46 132 111 236 82S414 48 512 84 642 100 680 74\"/><path d=\"M-30 103C75 69 132 134 236 105S414 71 512 107 642 123 680 97\"/><path d=\"M-30 126C75 92 132 157 236 128S414 94 512 130 642 146 680 120\"/><path d=\"M-30 149C75 115 132 180 236 151S414 117 512 153 642 169 680 143\"/><path d=\"M-30 172C75 138 132 203 236 174S414 140 512 176 642 192 680 166\"/><path d=\"M-30 195C75 161 132 226 236 197S414 163 512 199 642 215 680 189\"/><path d=\"M-30 218C75 184 132 249 236 220S414 186 512 222 642 238 680 212\"/><path d=\"M-30 241C75 207 132 272 236 243S414 209 512 245 642 261 680 235\"/><path d=\"M-30 264C75 230 132 295 236 266S414 232 512 268 642 284 680 258\"/><path d=\"M-30 287C75 253 132 318 236 289S414 255 512 291 642 307 680 281\"/></g><g class=\"field-cross-modes\"><path d=\"M35 -20C73 81 1 184 43 340\"/><path d=\"M107 -20C145 81 73 184 115 340\"/><path d=\"M179 -20C217 81 145 184 187 340\"/><path d=\"M251 -20C289 81 217 184 259 340\"/><path d=\"M323 -20C361 81 289 184 331 340\"/><path d=\"M395 -20C433 81 361 184 403 340\"/><path d=\"M467 -20C505 81 433 184 475 340\"/><path d=\"M539 -20C577 81 505 184 547 340\"/><path d=\"M611 -20C649 81 577 184 619 340\"/></g><g class=\"field-contours\"><ellipse cx=\"320\" cy=\"161\" rx=\"113\" ry=\"65\"/><ellipse cx=\"320\" cy=\"161\" rx=\"179\" ry=\"100\"/><ellipse cx=\"320\" cy=\"161\" rx=\"246\" ry=\"135\"/></g></svg>\n<p class=\"field-scene-label\">同一自由电子场 · 结构纹理</p>\n<div class=\"field-particles\" aria-hidden=\"true\"><span class=\"quantum\" id=\"chaos-electron\">e⁻</span><span class=\"quantum positron\" id=\"chaos-positron\">e⁺</span></div>\n<p class=\"field-scene-bottom\">背景始终保留</p>\n</div>\n<p class=\"vacuum-status\" id=\"chaos-vacuum-status\">基态：无电子与正电子激发</p>\n<div class=\"choices\" aria-label=\"选择自由电子场的示意状态\"><button class=\"choice\" type=\"button\" data-vacuum=\"ground\" aria-pressed=\"true\">基态</button><button class=\"choice\" type=\"button\" data-vacuum=\"electron\" aria-pressed=\"false\">电子激发态</button><button class=\"choice\" type=\"button\" data-vacuum=\"pair\" aria-pressed=\"false\">电子与正电子激发态</button></div>\n<p id=\"chaos-vacuum-note\" class=\"readout\" aria-live=\"polite\"><strong>基态：</strong>没有电子或正电子激发，允许怎样的激发仍由场的理论结构规定。</p>\n</div>\n<aside class=\"field-reading\" aria-labelledby=\"chaos-field-reading-title\" aria-live=\"polite\"><p class=\"field-reading-label\" id=\"chaos-field-reading-title\">由基态，理解未显的可能</p><p class=\"field-core\">尚无具体激发，<br>生成的可能与结构仍在。</p><dl class=\"field-parallels\"><div><dt>混沌</dt><dd id=\"chaos-field-chaos\">具体区别尚未展开，形成万物的能力仍在。</dd></div><div><dt>Hyle</dt><dd id=\"chaos-field-hyle\">尚未成形而能够受形，潜能可以进入生成。</dd></div><div><dt>渊</dt><dd id=\"chaos-field-abyss\">显现尚未展开，深广的可能并未被用尽。</dd></div></dl></aside>\n</div>\n<figcaption class=\"caption\">细线表示有结构的背景，圆点表示所选激发，均为概念记号。这是一种哲学对照：混沌、Hyle、“渊”与自由电子场各有自身含义。按钮比较不同状态，不模拟粒子产生过程。</figcaption>\n</figure>\n<div class=\"comparison\">\n<div class=\"comparison-item\"><span class=\"mark\" aria-hidden=\"true\">Ⅲ</span><div><h3>狄拉克海：一幅历史性的真空图景</h3><p>早期狄拉克海图景把负能态设想为被电子填满：在这片“海”中少了一个电子，留下的空穴可以与正电子相联系。它提供了海、背景与可见粒子的另一种思考方式。</p><p>这是一种具有具体理论来历的历史解释。现代量子场论对真空与反粒子采用了更合适的描述。</p></div></div>\n<div class=\"comparison-item\"><span class=\"mark\" aria-hidden=\"true\">Ⅳ</span><div><h3>电子场基态：用同一场理解粒子与反粒子</h3><p>在现代自由狄拉克场的量子化中，基态没有电子或正电子激发；相应的产生算符作用后，可以得到电子或正电子激发态。电子与正电子在同一场的描述中得到位置。</p><p>这使“背景—激发”的关系更清楚：具体粒子尚未出现，允许怎样的粒子出现却已有理论结构。相互作用理论的完整真空更复杂，此处采用自由场作为理解入口。</p></div></div>\n</div>\n<div class=\"model-card\" aria-label=\"历史狄拉克海与现代自由电子场的比较\"><div><h4>历史图景 · 狄拉克海</h4><div class=\"levels\" aria-hidden=\"true\"><div class=\"level\"><span>正能</span><span class=\"level-line\"></span></div><div class=\"level zero\"><span>分界</span><span class=\"level-line\"></span></div><div class=\"level\"><span>负能</span><span class=\"level-line\">●　●　●　●</span></div><div class=\"level\"><span>负能</span><span class=\"level-line\">●　●　<span id=\"chaos-dirac-hole\">●</span>　●</span></div><div class=\"level\"><span>负能</span><span class=\"level-line\">●　●　●　●</span></div></div><div class=\"choices\" aria-label=\"查看历史狄拉克海中的空穴\"><button class=\"choice\" type=\"button\" data-dirac=\"filled\" aria-pressed=\"true\">负能态填满</button><button class=\"choice\" type=\"button\" data-dirac=\"hole\" aria-pressed=\"false\">留下一个空穴</button></div><p class=\"model-caption\" id=\"chaos-dirac-note\" aria-live=\"polite\">在历史海图景中，负能态被设想为电子填满。</p></div><div><h4>现代描述 · 自由电子场</h4><div class=\"concept-flow\" style=\"grid-template-columns:1fr 20px 1fr;margin-top:22px\"><div class=\"node\">基态<small>无 e⁻、e⁺ 激发</small></div><span class=\"arrow\" aria-hidden=\"true\">→</span><div class=\"node\">激发态<small>电子／正电子</small></div></div><p class=\"model-caption\">分别定义电子、正电子的产生与湮灭算符，真空由两类湮灭算符共同定义。</p><p class=\"model-caption\"><strong>回到混沌 · Hyle · 渊：</strong>借基态与激发的对照，理解尚未显现与具体成形的关系；背景并未被一次显现用尽。</p></div></div>\n<details class=\"action-fold dao-fold\"><summary>延伸对读：玻姆的“隐秩序”与深层背景</summary><div class=\"inside action-prose\"><p>玻姆以更深背景中相对稳定的涟漪，帮助理解物质与整体过程的关系。这为“渊与显现”提供了另一层哲学思考。隐秩序、玻姆的量子动力学方案与现代量子场论各有自身的概念和理论，不能直接互换。</p></div></details>\n<h3>把这些对照放回各自的问题</h3>\n<table class=\"concept-table\"><thead><tr><th scope=\"col\">对照</th><th scope=\"col\">照亮的关系</th><th scope=\"col\">保留的含义</th></tr></thead><tbody><tr><th scope=\"row\">Hyle</th><td>潜能与形式</td><td>无形、接受形式、进入活动。</td></tr><tr><th scope=\"row\">渊</th><td>未显与显现</td><td>深广、未尽的哲学意象。</td></tr><tr><th scope=\"row\">海森堡</th><td>潜能与现实化</td><td>物理学家自己的哲学比较。</td></tr><tr><th scope=\"row\">量子真空</th><td>状态与激发</td><td>特定理论中的最低能量状态。</td></tr><tr><th scope=\"row\">狄拉克海</th><td>填充背景与空穴</td><td>解释真空与反粒子的历史图景。</td></tr><tr><th scope=\"row\">电子场基态</th><td>同一场与不同激发</td><td>自由场中的真空、电子与正电子。</td></tr></tbody></table>\n<p class=\"note\">这些材料使“生”可以被问得更具体：什么尚未显现？什么结构已经成立？怎样的条件允许形式出现？哲学对读借此追问潜能与显现，各种物理模型仍须依其理论含义理解。</p>\n</section>\n<section class=\"section\" id=\"chaos-whole\" aria-labelledby=\"chaos-whole-title\">\n<div class=\"section-title\"><span class=\"num\">07</span><h2 id=\"chaos-whole-title\">本自具足：潜能尚待展开</h2></div>\n<div class=\"prose\"><p>从整体来看，万物包含于其中，整体之外没有另一个存在。“本自具足”说明这一根本存在无所欠缺，生成的可能并未因此固定为全部已完成的结果；“尚未成为具体万物”说明丰富的可能还没有获得各自的形式。</p><p>于是，完整与未展开能够同时被说明：<strong>生成的能力已经在，具体的形式与经验仍可展开。</strong>混沌所要表达的，正是这一层未分化而能够生成的整体状态。</p><p>Hyle 帮助我们追问形式如何出现；空性帮助我们理解依待而有；“渊”与物理对读帮助我们辨认背景和显现。它们共同把本节的中心问题照亮，而各自仍保留不同的含义。</p></div>\n<p class=\"closing-line\">形态尚未展开，<br>形成万物的可能已经蕴含其中。</p>\n<div class=\"bridge\"><div class=\"kicker\">由一，走向二</div><p>接下来，我们还需要回答：</p><p class=\"question\">既然本自具足，<br>为什么仍要展开为万物，<br>进入对自身的经验？</p><p class=\"prose\">1.3「二：极性」将从这个问题开始，讨论创造意愿、经验与参照，再进入整体内部的此与彼、阴与阳。</p></div>\n</section></article></div>\n</div>";

export function chaosPage(){return markup;}

export function initChaosReading(root){

const scope=root.matches?.('.chaos-reading')?root:root.querySelector('.chaos-reading');
if(!scope)return ()=>{};
const controller=new AbortController(),signal=controller.signal,doc=scope.ownerDocument;
const $=selector=>scope.querySelector(selector),$$=selector=>[...scope.querySelectorAll(selector)];
const on=(element,type,handler)=>element.addEventListener(type,handler,{signal});
function select(attr,value){$$('['+attr+']').forEach(b=>b.setAttribute('aria-pressed',String(b.getAttribute(attr)===String(value))))}
function note(target,head,body){const n=$(target);n.replaceChildren(Object.assign(doc.createElement('strong'),{textContent:head+'：'}),doc.createTextNode(body))}
const stages=[['未取得形式','这里强调具体区别尚未展开，同时保留能够生成的可能。'],['潜能进入活动','借 Hyle 的描述，追问未成形的可能如何参与生成、接受形式。'],['具体形式出现','事物已获得可以辨认的形式。潜能与已经成形的事物，处于不同的解释位置。']];
function stage(i){select('data-stage',i);$$('.stage-form').forEach((g,j)=>g.style.opacity=j<=i?'1':'.16');$$('[data-mobile-stage]').forEach((g,j)=>g.classList.toggle('reached',j<=i));note('#chaos-stage-note',...stages[i])}
$$('[data-stage]').forEach(b=>on(b,'click',()=>stage(Number(b.dataset.stage))));stage(0);
const clayForms={all:['多种可能','泥团尚未成为碗、瓶或鸟，却可以在相应的塑形活动中，取得其中一种形式。'],bowl:['成碗','泥在塑形中取得能盛物的形状。材料的可能，在这一次活动中成为一种具体形式。',333,275,276,203],vase:['成瓶','同样的泥可以在另一种塑形中，取得瓶的形式。尚未成形时，不能只把它理解成一个预先完成的碗。',982,207,187,207],bird:['成鸟','泥还可以被塑造成鸟。具体形式依赖塑形的方式；一份能力可以容纳多种成形可能。',1454,348,203,163]};
$$('[data-clay]').forEach(b=>on(b,'click',()=>{const v=b.dataset.clay,d=clayForms[v];select('data-clay',v);$('#chaos-clay-veil').setAttribute('opacity',v==='all'?'0':'.84');$('#chaos-clay-ring').setAttribute('opacity',v==='all'?'0':'1');if(v!=='all')for(const id of ['#chaos-clay-hole','#chaos-clay-ring'])['cx','cy','rx','ry'].forEach((attr,i)=>$(id).setAttribute(attr,d[i+2]));note('#chaos-clay-note',d[0],d[1])}));
const flowers={form:['看见形态','一朵花已经成形，具有可以辨认的样子。'],conditions:['看见依待','阳光、水分、种子、土壤等参与它的生长。选择下方条件，可以逐项查看。'],empty:['理解无自性','花仍然在。它依待条件而有，无法从自身独立成立。已经成形的事物，同样可以被理解为无自性。']};
$$('[data-flower]').forEach(b=>on(b,'click',()=>{const v=b.dataset.flower;select('data-flower',v);$('#chaos-flower-guides').setAttribute('opacity',v==='form'?'0':'.8');$('#chaos-flower-focus').setAttribute('opacity','0');$('#chaos-flower-condition-picker').hidden=v==='form';$$('[data-condition]').forEach(b=>b.setAttribute('aria-pressed','false'));note('#chaos-flower-note',...flowers[v])}));
const conditions={light:['阳光','光照参与植物的生长。具体需要怎样的光照，由植物种类与生长阶段等条件共同决定。',226,147,140,123],water:['水分','水分参与植物的生理活动。土壤、根系与水分之间，也形成依存关系。',1371,260,110,190],soil:['土壤与根系','根系从适宜的环境中获取水分与养分。土壤、根系和其他条件一起，使这朵花能够生长。',709,730,305,171],seed:['种子与过程','眼前的花经历了萌发与生长。它的形态包含此前的过程，不能脱离来路独立成立。',1452,778,109,102],name:['辨认与命名','我们依据花瓣、枝叶、整体形态等，将它辨认为“花”。这种依待说明识别方式，与阳光水分的生长作用分别理解。',715,354,304,268]};
$$('[data-condition]').forEach(b=>on(b,'click',()=>{const v=b.dataset.condition,d=conditions[v];select('data-condition',v);['cx','cy','rx','ry'].forEach((attr,i)=>$('#chaos-flower-focus').setAttribute(attr,d[i+2]));$('#chaos-flower-focus').setAttribute('opacity','1');note('#chaos-flower-note',d[0],d[1])}));
$$('[data-dirac]').forEach(b=>on(b,'click',()=>{const v=b.dataset.dirac;select('data-dirac',v);$('#chaos-dirac-hole').textContent=v==='filled'?'●':'○';$('#chaos-dirac-hole').classList.toggle('is-hole',v==='hole');$('#chaos-dirac-note').textContent=v==='filled'?'在历史海图景中，负能态被设想为电子填满。':'少了一个电子，留下的空穴对应正电子。这是历史图景中的解释方式。'}));
$$('[data-sea]').forEach(b=>on(b,'click',()=>{const v=b.dataset.sea;select('data-sea',v);$('#chaos-sea-detail').style.opacity=v==='wave'?'.08':'1';$('#chaos-sea-depth-label').style.opacity=v==='wave'?'.12':'1';$('#chaos-sea-note').textContent=v==='wave'?'只看这一道浪，我们能辨认它的轮廓。':'这一道浪显出形状，海仍有超出这一形状的深广。'}));
const fieldStates={
ground:{head:'基态',body:'没有电子或正电子激发，允许怎样的激发仍由场的理论结构规定。',status:'基态：无电子与正电子激发',image:'基态：层叠细线表示始终存在的理论结构，没有电子或正电子激发',chaos:'具体区别尚未展开，形成万物的能力仍在。',hyle:'尚未成形而能够受形，潜能可以进入生成。',abyss:'显现尚未展开，深广的可能并未被用尽。'},
electron:{head:'电子激发态',body:'一个电子激发被具体标出，背景结构仍在。这是在比较不同状态，并未演示真空无条件地产生电荷。',status:'电子激发态：一个电子激发',image:'电子激发态：一个电子标记显现，整体结构纹理继续保留',chaos:'一种具体区别显出，整体的可能没有被这一呈现穷尽。',hyle:'从未成形到受形：借具体激发，思考潜能取得形式的关系。',abyss:'一道“浪形”显现，深广的背景仍超出这一具体呈现。'},
pair:{head:'电子与正电子激发态',body:'同一自由电子场容纳电子与正电子激发。具体产生过程仍须满足能量、电荷等物理条件。',status:'电子与正电子激发态：两种激发共同呈现',image:'电子与正电子激发态：电子和正电子标记同时显现，整体结构纹理继续保留',chaos:'不同的具体呈现出现，仍须放回整体理解。',hyle:'潜能可以取得不同形式，并不等于预先存放了全部成品。',abyss:'不同的“浪形”显现，仍未用尽背景的深广。'}
};
function renderFieldState(value){const state=fieldStates[value];if(!state)return;select('data-vacuum',value);$('#chaos-field-scene').dataset.fieldState=value;$('#chaos-field-scene').setAttribute('aria-label',state.image);$('#chaos-electron').classList.toggle('visible',value!=='ground');$('#chaos-positron').classList.toggle('visible',value==='pair');note('#chaos-vacuum-note',state.head,state.body);$('#chaos-vacuum-status').textContent=state.status;$('#chaos-field-chaos').textContent=state.chaos;$('#chaos-field-hyle').textContent=state.hyle;$('#chaos-field-abyss').textContent=state.abyss;}
$$('[data-vacuum]').forEach(button=>on(button,'click',()=>renderFieldState(button.dataset.vacuum)));
renderFieldState('ground');

return ()=>controller.abort();
}
